package cn.yueji.balance;

import java.time.*;
import java.util.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class V4713RulesTest {
    Ledger.Data data(){Ledger.Data d=new Ledger.Data();d.watchFunds.add(new Ledger.WatchFund("000001","合成基金A"));d.watchFunds.add(new Ledger.WatchFund("000002","合成基金B"));d.watchGroups.add(new Ledger.WatchGroup(1,"原分组"));d.watchGroups.get(0).codes.add("000001");return d;}
    FundProfile limit(String value){FundProfile p=new FundProfile();p.readDailyLimit("<tr><td>日累计申购限额</td><td class='w135'>"+value+"</td></tr>","");return p;}
    Ledger.Entry entry(Ledger.Data d,String kind,long amount,String date){Ledger.Entry e=new Ledger.Entry(d.nextId(),Ledger.INCOME.equals(kind),amount,LocalDateTime.parse(date),"合成记录","",0);e.kind=kind;e.category="其他";d.entries.add(e);return e;}
    @Test public void parseDailyAmountNotMinimumOrSingleOrder(){FundProfile p=new FundProfile();p.readDailyLimit("<td>申购起点</td><td>10.00元</td><td>单笔购买上限</td><td>100.00元</td>","暂停申购");assertFalse(p.dailyLimitConfirmed);assertFalse(p.limited());assertEquals("",p.limitLabel());}
    @Test public void parseConfirmedTenYuanLimit(){FundProfile p=limit("10.00元");assertTrue(p.dailyLimitConfirmed);assertTrue(p.limited());assertEquals("10.00元",p.dailyLimit);assertEquals("限制单日买入10元",p.limitLabel());assertFalse(p.dailyLimitChecked.isEmpty());p.validate();}
    @Test public void parseThousandsAndTenThousands(){assertEquals("1234.56元",limit("1,234.56元").dailyLimit);assertEquals("50000.00元",limit("5万元").dailyLimit);assertEquals("2000.00元",limit("2千元").dailyLimit);}
    @Test public void explicitUnlimitedIsDifferentFromUnknown(){FundProfile p=limit("无限额");assertTrue(p.dailyLimitConfirmed);assertFalse(p.limited());assertEquals("",p.dailyLimit);assertFalse(limit("---").dailyLimitConfirmed);assertFalse(limit("无法获取").dailyLimitConfirmed);}
    @Test public void hugeOrMalformedLimitIsUnknownNotZero(){assertFalse(limit("9999999999999999999999亿元").dailyLimitConfirmed);assertFalse(limit("-20元").dailyLimitConfirmed);assertFalse(limit("1,00.00元").dailyLimitConfirmed);}
    @Test public void suspendedFundCanStillDiscloseALimitWithoutImplyingTrading(){FundProfile p=new FundProfile();p.readDailyLimit("暂停申购<td>日累计申购限额</td><td>10.00元</td>","");assertTrue(p.limited());assertEquals("10.00元",p.dailyLimit);}
    @Test public void explicitDailyOverviewFallbackWorks(){FundProfile p=new FundProfile();p.readDailyLimit("","单日累计购买上限100元");assertTrue(p.limited());assertEquals("100.00元",p.dailyLimit);}
    @Test public void partialOrFailedResponsePreservesKnownLimit(){FundProfile old=limit("50元");old.merge(new FundProfile());assertTrue(old.limited());assertEquals("50.00元",old.dailyLimit);}
    @Test public void laterExplicitUnlimitedClearsAnOldLimit(){FundProfile old=limit("50元"),unlimited=limit("无限额");unlimited.dailyLimitChecked=FundEngine.now().toString();old.merge(unlimited);assertFalse(old.limited());assertTrue(old.dailyLimitConfirmed);}
    @Test public void staleResponseCannotReplaceNewerPurchaseLimit(){FundProfile old=limit("50元"),stale=limit("10元");old.dailyLimitChecked="2026-10-30T20:00";stale.dailyLimitChecked="2026-10-30T10:00";old.merge(stale);assertEquals("50.00元",old.dailyLimit);}
    @Test public void firstClassificationMovesOutOfOtherUserGroupsAndInbox(){Ledger.Data d=data();d.watchAllIncluded.add("000001");WatchlistScreens.applyProfile(d,"000001",limit("10元"));assertTrue(WatchGroups.member(d,"000001",WatchGroups.LIMITED));assertFalse(WatchGroups.member(d,"000001","原分组"));assertFalse(WatchGroups.member(d,"000001","全部"));assertTrue(d.watchLimitClassified.contains("000001"));assertFalse(WatchGroups.member(d,"000002",WatchGroups.LIMITED));}
    @Test public void laterManualGroupAndInboxAdditionsSurviveRepeatedRefreshAndBackup(){Ledger.Data d=data();WatchlistScreens.applyProfile(d,"000001",limit("10元"));WatchGroups.move(d,"000001",WatchGroups.LIMITED,1,true);WatchGroups.move(d,"000001",WatchGroups.LIMITED,0,true);WatchlistScreens.applyProfile(d,"000001",limit("20元"));LedgerStore.validate(d);d=LedgerStore.decode(LedgerStore.encode(d));LedgerStore.validate(d);assertTrue(WatchGroups.member(d,"000001",WatchGroups.LIMITED));assertTrue(WatchGroups.member(d,"000001","原分组"));assertTrue(WatchGroups.member(d,"000001","全部"));}
    @Test public void explicitUnlimitedLeavesSystemGroupWithoutDeletingFundOrUserCopies(){Ledger.Data d=data();WatchlistScreens.applyProfile(d,"000001",limit("10元"));WatchGroups.move(d,"000001",WatchGroups.LIMITED,1,false);WatchlistScreens.applyProfile(d,"000001",limit("无限额"));assertFalse(WatchGroups.member(d,"000001",WatchGroups.LIMITED));assertTrue(WatchGroups.member(d,"000001","原分组"));assertFalse(d.watchLimitClassified.contains("000001"));assertEquals(2,d.watchFunds.size());}
    @Test public void unknownRefreshCannotRemoveConfirmedSystemMembership(){Ledger.Data d=data();WatchlistScreens.applyProfile(d,"000001",limit("10元"));WatchlistScreens.applyProfile(d,"000001",new FundProfile());assertTrue(WatchGroups.member(d,"000001",WatchGroups.LIMITED));}
    @Test public void oldUnverifiedHeuristicDoesNotCreateSystemMembership(){Ledger.Data d=data();d.watchFunds.get(0).profile.dailyLimit="100元";LedgerStore.validate(d);assertFalse(WatchGroups.member(d,"000001",WatchGroups.LIMITED));assertTrue(WatchGroups.member(d,"000001","原分组"));}
    @Test public void ownedMembershipIsTruthfulAndExplicitWatchMembershipIsIndependent(){Ledger.Data d=new Ledger.Data();Ledger.Fund f=new Ledger.Fund();f.id=1;f.code="000001";f.name="合成持仓";f.profile.merge(limit("10元"));d.funds.add(f);WatchGroups.reconcile(d);assertTrue(WatchGroups.held(d,f.code));assertFalse(WatchGroups.member(d,f.code,"持有"));assertTrue(WatchGroups.member(d,f.code,WatchGroups.LIMITED));assertFalse(WatchGroups.explicit(d,f.code));d.watchFunds.add(WatchAnalytics.owned(f));assertTrue(WatchGroups.explicit(d,f.code));assertEquals(0,d.entries.size());}
    @Test public void oldCustomGroupWithReservedNameIsRenamedWithoutDataLoss()throws Exception{Ledger.Data d=data();d.watchGroups.get(0).name="定投";JSONObject old=new JSONObject(LedgerStore.encode(d)).put("version",17);Ledger.Data r=LedgerStore.decode(old.toString());assertEquals("定投(原分组)",r.watchGroups.get(0).name);assertTrue(r.watchGroups.get(0).codes.contains("000001"));assertFalse(WatchGroups.member(r,"000001",WatchGroups.LIMITED));LedgerStore.validate(r);}
    @Test public void roundTripKeepsClassificationAndVerifiedLimit()throws Exception{Ledger.Data d=data();WatchlistScreens.applyProfile(d,"000001",limit("50元"));LedgerStore.validate(d);String json=LedgerStore.encode(d);assertEquals(18,new JSONObject(json).getInt("version"));Ledger.Data r=LedgerStore.decode(json);LedgerStore.validate(r);assertEquals(json,LedgerStore.encode(r));assertEquals("50.00元",r.watchFunds.get(0).profile.dailyLimit);assertTrue(r.watchLimitClassified.contains("000001"));}
    @Test public void currentAndMostRecentEarlierMonthsAreSummedByKind(){Ledger.Data d=new Ledger.Data();entry(d,Ledger.INCOME,100,"2026-11-01T01:00");entry(d,Ledger.INCOME,200,"2026-09-01T01:00");entry(d,Ledger.INCOME,300,"2026-09-20T01:00");entry(d,Ledger.INCOME,1000,"2026-06-01T01:00");entry(d,Ledger.LARGE,999,"2026-10-01T01:00");EntryMonths.Summary s=EntryMonths.calculate(d,Ledger.INCOME,YearMonth.of(2026,11));assertEquals(100,s.current);assertEquals(500,s.previous);assertEquals("9月",s.previousLabel(YearMonth.of(2026,11)));}
    @Test public void immediatePriorMonthUsesLastMonthLabel(){Ledger.Data d=new Ledger.Data();entry(d,Ledger.LARGE,500,"2026-10-01T01:00");EntryMonths.Summary s=EntryMonths.calculate(d,Ledger.LARGE,YearMonth.of(2026,11));assertEquals(0,s.current);assertEquals(500,s.previous);assertEquals("上月",s.previousLabel(YearMonth.of(2026,11)));}
    @Test public void missingAllPriorMonthsStillShowsZeroValue(){EntryMonths.Summary s=EntryMonths.calculate(new Ledger.Data(),Ledger.INCOME,YearMonth.of(2026,11));assertEquals(0,s.previous);assertNull(s.previousMonth);assertEquals("上月",s.previousLabel(YearMonth.of(2026,11)));}
    @Test public void crossYearOlderMonthIncludesYear(){Ledger.Data d=new Ledger.Data();entry(d,Ledger.INCOME,700,"2024-12-01T01:00");EntryMonths.Summary s=EntryMonths.calculate(d,Ledger.INCOME,YearMonth.of(2026,1));assertEquals("2024年12月",s.previousLabel(YearMonth.of(2026,1)));}
    @Test public void zeroAmountPresenceDoesNotSkipTheMonth(){Ledger.Data d=new Ledger.Data();entry(d,Ledger.INCOME,0,"2026-10-01T01:00");entry(d,Ledger.INCOME,900,"2026-09-01T01:00");EntryMonths.Summary s=EntryMonths.calculate(d,Ledger.INCOME,YearMonth.of(2026,11));assertEquals(0,s.previous);assertEquals("上月",s.previousLabel(YearMonth.of(2026,11)));}
    @Test public void reimbursementSummaryUsesAdvanceMonthNotReceiptMonth(){Ledger.Data d=new Ledger.Data();Ledger.Entry e=entry(d,Ledger.REIMBURSE,80000,"2026-09-01T01:00");e.receipts.add(new Ledger.Receipt(80000,LocalDateTime.parse("2026-11-01T01:00")));EntryMonths.Summary s=EntryMonths.calculate(d,Ledger.REIMBURSE,YearMonth.of(2026,11));assertEquals(0,s.current);assertEquals(80000,s.previous);assertEquals("9月",s.previousLabel(YearMonth.of(2026,11)));}
    @Test public void rightAndLeftAssetCyclePreserveExistingPanelIds(){assertEquals(1,AssetPanels.step(2,1));assertEquals(0,AssetPanels.step(1,1));assertEquals(2,AssetPanels.step(0,1));assertEquals(0,AssetPanels.step(2,-1));assertEquals(2,AssetPanels.step(1,-1));}
    @Test public void colourRolesUseSourceTypeNotCashDirection(){Ledger.Data d=new Ledger.Data();Ledger.Account a=new Ledger.Account(1,"合成账户","银行");a.created=LocalDateTime.parse("2026-09-01T00:00");a.opening=500000;d.accounts.add(a);Ledger.Entry e=entry(d,Ledger.REIMBURSE,80000,"2026-10-01T01:00");e.accountId=1;e.cashLinked=true;Ledger.Receipt r=new Ledger.Receipt(80000,LocalDateTime.parse("2026-10-02T01:00"));r.accountId=1;r.cashLinked=true;e.receipts.add(r);for(AccountCash.Flow flow:AccountCash.flows(d))assertEquals(RecordColors.Role.REIMBURSE,RecordColors.flow(d,flow));assertEquals(RecordColors.Role.INCOME,RecordColors.entry(Ledger.INCOME));assertEquals(RecordColors.Role.EXPENSE,RecordColors.entry(Ledger.LARGE));assertEquals(RecordColors.Role.INVESTMENT,RecordColors.entry(Ledger.INVEST_OUT));}
    @Test public void defaultTransferUsesKnownCurrentCashBalanceIncludingLaterIncome(){Ledger.Data d=new Ledger.Data();Ledger.Account a=new Ledger.Account(1,"合成账户","银行");a.created=LocalDateTime.parse("2026-09-01T00:00");a.opening=100000;d.accounts.add(a);Ledger.Entry e=entry(d,Ledger.INCOME,50000,"2026-10-01T01:00");e.accountId=1;e.cashLinked=true;assertEquals("1500.00",TransferScreens.defaultAmount(d,a));assertEquals("",TransferScreens.defaultAmount(d,null));a.openingKnown=false;assertEquals("",TransferScreens.defaultAmount(d,a));}
    @Test public void explicitZeroDailyCapIsNotMisreadAsUnlimited(){FundProfile p=limit("0.00元");assertTrue(p.dailyLimitConfirmed);assertTrue(p.limited());assertEquals("限制单日买入0元",p.limitLabel());}
    @Test(expected=IllegalArgumentException.class) public void duplicateClassificationMarkersAreRejected()throws Exception{JSONObject o=new JSONObject(LedgerStore.encode(data()));o.put("watchLimitClassified",new JSONArray().put("000001").put("000001"));LedgerStore.decode(o.toString());}
    @Test(expected=java.time.DateTimeException.class) public void malformedLimitCheckTimeRejected(){FundProfile p=limit("10元");p.dailyLimitChecked="not a date";p.validate();}
    @Test(expected=IllegalArgumentException.class) public void cannotManuallyMoveIntoAutomaticGroup(){WatchGroups.move(data(),"000001","原分组",-1,true);}
    @Test(expected=IllegalArgumentException.class) public void cannotCreateReservedCustomGroup(){Ledger.Data d=data();d.watchGroups.get(0).name=WatchGroups.LIMITED;LedgerStore.validate(d);}
    @Test(expected=IllegalArgumentException.class) public void invalidClassifierFieldRejected()throws Exception{JSONObject o=new JSONObject(LedgerStore.encode(data()));o.put("watchLimitClassified",new JSONArray().put(123));LedgerStore.decode(o.toString());}
    @Test(expected=IllegalArgumentException.class) public void missingClassifierCodeRejected()throws Exception{JSONObject o=new JSONObject(LedgerStore.encode(data()));o.put("watchLimitClassified",new JSONArray().put("999999"));LedgerStore.decode(o.toString());}
    @Test(expected=IllegalArgumentException.class) public void malformedLimitFlagRejected()throws Exception{Ledger.Data d=data();JSONObject o=new JSONObject(LedgerStore.encode(d));o.getJSONArray("watchFunds").getJSONObject(0).getJSONObject("profile").put("dailyLimitConfirmed","true");LedgerStore.decode(o.toString());}
    @Test(expected=IllegalArgumentException.class) public void malformedVerifiedMoneyRejected(){FundProfile p=limit("10元");p.dailyLimit="not money";p.validate();}
}
